import{_ as e,o as r,c as o,a3 as a}from"./chunks/framework.B5WAEDB7.js";const m=JSON.parse('{"title":"Apollo Lite 资源下载","description":"Apollo Lite 的模型、感知、规划、控制、标定、工程工具和数据地图服务入口。","frontmatter":{"title":"Apollo Lite 资源下载","description":"Apollo Lite 的模型、感知、规划、控制、标定、工程工具和数据地图服务入口。","status":"仓库事实","content_type":"resources","keywords":["Apollo Lite","感知模型","规划控制","标定","工程工具"]},"headers":[],"relativePath":"resources/index.md","filePath":"resources/index.md","lastUpdated":1794216847000}'),l={name:"resources/index.md"};function d(h,t,i,n,s,c){return r(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="apollo-lite-资源下载" tabindex="-1">Apollo Lite 资源下载 <a class="header-anchor" href="#apollo-lite-资源下载" aria-label="Permalink to &quot;Apollo Lite 资源下载&quot;">​</a></h1><p>这里面向 <a href="https://github.com/wheelos/apollo-lite" target="_blank" rel="noreferrer">Apollo Lite</a> 的开发、集成、标定与验证，整理 Lite 工程中实际支持的模型、功能算法、工具包，以及 WheelOS 自有的数据和地图服务。</p><p>资源条目优先链接到 Apollo Lite 的代码、配置和文档；服务类资源预留 WheelOS 服务入口，不把尚未公开的地址伪装成可下载链接。页面中的“已实现”表示代码或配置存在，不等同于在所有车型和道路环境中完成量产验证。</p><h2 id="按开发任务查找" tabindex="-1">按开发任务查找 <a class="header-anchor" href="#按开发任务查找" aria-label="Permalink to &quot;按开发任务查找&quot;">​</a></h2><table tabindex="0"><thead><tr><th>任务</th><th>资源入口</th></tr></thead><tbody><tr><td>准备感知模型和推理配置</td><td><a href="#模型与推理资源">模型</a></td></tr><tr><td>开启地面检测、车道线或障碍物感知</td><td><a href="#感知算法包">感知算法包</a></td></tr><tr><td>开发精准停车和无地图规划</td><td><a href="#规划与停车算法包">规划与停车算法包</a></td></tr><tr><td>做车辆动力学、横纵向控制标定</td><td><a href="#标定与控制算法包">标定与控制算法包</a></td></tr><tr><td>采集、回放、可视化和排查问题</td><td><a href="#工程工具">工程工具</a></td></tr><tr><td>获取车辆数据或生成地图</td><td><a href="#wheelos-数据服务">WheelOS 数据服务</a> · <a href="#wheelos-地图服务">WheelOS 地图服务</a></td></tr></tbody></table><h2 id="模型与推理资源" tabindex="-1">模型与推理资源 <a class="header-anchor" href="#模型与推理资源" aria-label="Permalink to &quot;模型与推理资源&quot;">​</a></h2><p>以下条目对应 Lite 中的模型文件、模型配置或推理适配代码。下载模型时应同时获取对应的 <code>conf</code>、传感器参数和模型版本，不能只替换一个权重文件。</p><table tabindex="0"><thead><tr><th>资源</th><th>Lite 中的用途</th><th>主要内容</th><th>入口</th></tr></thead><tbody><tr><td>相机障碍物模型</td><td>相机障碍物检测</td><td>YOLO、YOLOv4、SMOKE 检测器及后处理</td><td><a href="https://github.com/wheelos/apollo-lite/tree/main/modules/perception/camera" target="_blank" rel="noreferrer">perception/camera</a> · <a href="https://github.com/wheelos/apollo-lite/tree/main/modules/perception/production/data/perception/camera/models" target="_blank" rel="noreferrer">模型配置</a></td></tr><tr><td>相机车道线模型</td><td>车道线检测和车道线标定</td><td>Lane、DarkSCNN、Denseline 后处理</td><td><a href="https://github.com/wheelos/apollo-lite/tree/main/modules/lane" target="_blank" rel="noreferrer">lane 模块</a> · <a href="https://github.com/wheelos/apollo-lite/tree/main/modules/perception/production/data/perception/camera/models/lane_detector" target="_blank" rel="noreferrer">相机模型</a></td></tr><tr><td>交通灯模型</td><td>交通灯检测与识别</td><td>检测、识别模型及生产配置</td><td><a href="https://github.com/wheelos/apollo-lite/tree/main/modules/perception/production/data/perception/camera/models/traffic_light_detection" target="_blank" rel="noreferrer">交通灯配置</a> · <a href="https://github.com/wheelos/apollo-lite/tree/main/modules/perception/production/data/perception/camera/models/traffic_light_recognition" target="_blank" rel="noreferrer">识别配置</a></td></tr><tr><td>LiDAR 障碍物模型</td><td>点云障碍物检测和分割</td><td>CNNSEG、NCUT、中心点和时空地面检测相关配置</td><td><a href="https://github.com/wheelos/apollo-lite/tree/main/modules/perception/lidar" target="_blank" rel="noreferrer">LiDAR 感知</a> · <a href="https://github.com/wheelos/apollo-lite/tree/main/modules/perception/production/data/perception/lidar/models" target="_blank" rel="noreferrer">LiDAR 模型配置</a></td></tr><tr><td>相机语义分割模型</td><td>相机语义分割推理</td><td>SegFormer 的 ONNX/TensorRT 导出和构建工具</td><td><a href="https://github.com/wheelos/apollo-lite/tree/main/modules/camera_semantic_segmentation" target="_blank" rel="noreferrer">camera_semantic_segmentation</a></td></tr></tbody></table><p>**模型条目建议字段：**传感器和内参、类别定义、输入尺寸、推理后端、TensorRT/CUDA 版本、显存、单帧时延、模型校验和、训练/评测范围和已知失效场景。</p><h2 id="感知算法包" tabindex="-1">感知算法包 <a class="header-anchor" href="#感知算法包" aria-label="Permalink to &quot;感知算法包&quot;">​</a></h2><p>这些是按 Lite 功能组织的算法包，不是泛化的开源算法推荐。</p><table tabindex="0"><thead><tr><th>功能包</th><th>能力范围</th><th>Lite 代码入口</th></tr></thead><tbody><tr><td>地面检测</td><td>LiDAR 地面服务、地面服务检测器、时空地面检测和地面分割</td><td><a href="https://github.com/wheelos/apollo-lite/tree/main/modules/perception/lidar/lib/ground_detector" target="_blank" rel="noreferrer">ground_detector</a> · <a href="https://github.com/wheelos/apollo-lite/tree/main/modules/perception/lidar/lib/scene_manager/ground_service" target="_blank" rel="noreferrer">ground service</a></td></tr><tr><td>障碍物检测</td><td>相机、LiDAR、BEV 障碍物检测和离线检测</td><td><a href="https://github.com/wheelos/apollo-lite/tree/main/modules/perception/camera/lib/obstacle" target="_blank" rel="noreferrer">camera obstacle</a> · <a href="https://github.com/wheelos/apollo-lite/tree/main/modules/perception/lidar/lib/detector" target="_blank" rel="noreferrer">LiDAR detector</a></td></tr><tr><td>障碍物跟踪与融合</td><td>OMT/OMT2、多 LiDAR 融合、概率融合</td><td><a href="https://github.com/wheelos/apollo-lite/tree/main/modules/perception/camera/lib/obstacle/tracker" target="_blank" rel="noreferrer">tracking</a> · <a href="https://github.com/wheelos/apollo-lite/tree/main/modules/perception/fusion" target="_blank" rel="noreferrer">fusion</a></td></tr><tr><td>车道线感知</td><td>UFLDv2、DarkSCNN、Denseline 及车道线标定</td><td><a href="https://github.com/wheelos/apollo-lite/tree/main/modules/lane" target="_blank" rel="noreferrer">lane</a> · <a href="https://github.com/wheelos/apollo-lite/tree/main/modules/perception/camera/lib/lane" target="_blank" rel="noreferrer">lane perception</a></td></tr><tr><td>交通灯感知</td><td>交通灯检测、识别、预处理和可视化</td><td><a href="https://github.com/wheelos/apollo-lite/tree/main/modules/perception/camera/lib/traffic_light" target="_blank" rel="noreferrer">traffic light</a></td></tr><tr><td>定位</td><td>NDT、MSF、RTK 及定位健康监控</td><td><a href="https://github.com/wheelos/apollo-lite/tree/main/modules/localization" target="_blank" rel="noreferrer">localization</a> · <a href="https://github.com/wheelos/apollo-lite/tree/main/modules/localization_health" target="_blank" rel="noreferrer">localization health</a></td></tr></tbody></table><h2 id="规划与停车算法包" tabindex="-1">规划与停车算法包 <a class="header-anchor" href="#规划与停车算法包" aria-label="Permalink to &quot;规划与停车算法包&quot;">​</a></h2><table tabindex="0"><thead><tr><th>功能包</th><th>能力范围</th><th>Lite 代码入口</th></tr></thead><tbody><tr><td>精准停车</td><td>开放空间规划、泊车多挡位搜索、曲率约束轨迹平滑和碰撞安全检查</td><td><a href="https://github.com/wheelos/apollo-lite/tree/main/modules/open_space_planning" target="_blank" rel="noreferrer">open_space_planning</a> · <a href="https://github.com/wheelos/apollo-lite/tree/main/modules/planning/open_space/parking" target="_blank" rel="noreferrer">停车规划</a></td></tr><tr><td>无地图/开放空间规划</td><td>Skeleton Corridor、Hybrid A*、轨迹规划、轨迹验证和安全降级</td><td><a href="https://github.com/wheelos/apollo-lite/blob/main/modules/open_space_planning/README.md" target="_blank" rel="noreferrer">开放空间规划说明</a></td></tr><tr><td>参考线规划</td><td>车道跟随、交通规则、场景和任务规划</td><td><a href="https://github.com/wheelos/apollo-lite/tree/main/modules/planning" target="_blank" rel="noreferrer">planning</a></td></tr><tr><td>路由与相对地图</td><td>路由拓扑、相对地图和导航模式</td><td><a href="https://github.com/wheelos/apollo-lite/tree/main/modules/routing" target="_blank" rel="noreferrer">routing</a> · <a href="https://github.com/wheelos/apollo-lite/tree/main/modules/world_model/relative_map" target="_blank" rel="noreferrer">relative map</a></td></tr></tbody></table><h2 id="标定与控制算法包" tabindex="-1">标定与控制算法包 <a class="header-anchor" href="#标定与控制算法包" aria-label="Permalink to &quot;标定与控制算法包&quot;">​</a></h2><table tabindex="0"><thead><tr><th>功能包</th><th>能力范围</th><th>Lite 代码/工具入口</th></tr></thead><tbody><tr><td>动力学标定</td><td>执行器标定、横向车辆动力学测试、计划生成、CyberRT 采集、离线分析</td><td><a href="https://github.com/wheelos/apollo-lite/tree/main/whl-dyn" target="_blank" rel="noreferrer">whl-dyn</a> · <a href="https://github.com/wheelos/apollo-lite/blob/main/wheelos-service/context/modules/tools/whl-dyn-open-loop-calibration-tool.md" target="_blank" rel="noreferrer">工具说明</a></td></tr><tr><td>横纵向控制</td><td>MPC、纵向控制、横向控制、控制标定表和控制回放</td><td><a href="https://github.com/wheelos/apollo-lite/tree/main/modules/control" target="_blank" rel="noreferrer">control</a> · <a href="https://github.com/wheelos/apollo-lite/tree/main/modules/control/conf" target="_blank" rel="noreferrer">控制配置</a></td></tr><tr><td>传感器标定</td><td>相机、LiDAR、车道线和坐标变换相关标定</td><td><a href="https://github.com/wheelos/apollo-lite/tree/main/modules/calibration" target="_blank" rel="noreferrer">标定模块</a> · <a href="https://github.com/wheelos/apollo-lite/blob/main/scripts/sensor_calibration.sh" target="_blank" rel="noreferrer">sensor_calibration.sh</a></td></tr></tbody></table><h2 id="工程工具" tabindex="-1">工程工具 <a class="header-anchor" href="#工程工具" aria-label="Permalink to &quot;工程工具&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>用途</th><th>入口</th></tr></thead><tbody><tr><td><code>whl-dyn</code></td><td>动力学标定、测试计划、数据采集、离线指标和 Streamlit 工作台</td><td><a href="https://github.com/wheelos/apollo-lite/tree/main/whl-dyn" target="_blank" rel="noreferrer">whl-dyn README</a></td></tr><tr><td><code>whl-debug</code></td><td>控制器调试、线上/离线数据提取和问题定位</td><td><a href="https://github.com/wheelos/apollo-lite/tree/main/modules/tools/whl-debug" target="_blank" rel="noreferrer">whl-debug</a></td></tr><tr><td><code>whl-tools</code></td><td>相机语义分割、图像消息发布、车道线调试可视化</td><td><a href="https://github.com/wheelos/apollo-lite/tree/main/modules/tools/whl-tools" target="_blank" rel="noreferrer">whl-tools</a></td></tr><tr><td><code>whl_toolbox</code></td><td>点云、SLAM、传感器和运行时数据的可视化工具箱</td><td><a href="https://github.com/wheelos/apollo-lite/tree/main/modules/tools/whl_toolbox" target="_blank" rel="noreferrer">whl_toolbox</a></td></tr><tr><td><code>whl-can</code></td><td>CAN 自动测试、静态/动态用例和车辆接口验证</td><td><a href="https://github.com/wheelos/apollo-lite/tree/main/modules/tools/whl-can" target="_blank" rel="noreferrer">whl-can</a></td></tr><tr><td><code>whl-mock</code></td><td>路由、交通灯等输入消息的模拟发布</td><td><a href="https://github.com/wheelos/apollo-lite/tree/main/modules/tools/whl-mock" target="_blank" rel="noreferrer">whl-mock</a></td></tr><tr><td>地图工具</td><td>从 Mobileye、XY 等来源生成地图，以及路由拓扑图生成</td><td><a href="https://github.com/wheelos/apollo-lite/tree/main/modules/map/tools" target="_blank" rel="noreferrer">map/tools</a> · <a href="https://github.com/wheelos/apollo-lite/tree/main/scripts" target="_blank" rel="noreferrer">脚本</a></td></tr><tr><td>录制与回放</td><td>CyberRT 录制、消息记录、地图数据采集和回放启动</td><td><a href="https://github.com/wheelos/apollo-lite/blob/main/scripts/recording_launcher.py" target="_blank" rel="noreferrer">recording_launcher.py</a> · <a href="https://github.com/wheelos/apollo-lite/blob/main/scripts/record_map_data.py" target="_blank" rel="noreferrer">record_map_data.py</a></td></tr></tbody></table><h2 id="wheelos-数据服务" tabindex="-1">WheelOS 数据服务 <a class="header-anchor" href="#wheelos-数据服务" aria-label="Permalink to &quot;WheelOS 数据服务&quot;">​</a></h2><p>数据服务应作为 WheelOS 的自有产品提供，不把原始车辆数据直接散落在 Git 仓库中。建议从以下服务入口开始建设：</p><table tabindex="0"><thead><tr><th>服务</th><th>面向对象</th><th>建议提供的能力</th><th>当前状态</th></tr></thead><tbody><tr><td>数据集目录服务</td><td>算法、标定、测试开发</td><td>按车型/传感器/场景/版本检索，返回数据集 ID、时间范围、话题、格式、大小和权限</td><td>服务入口待接入</td></tr><tr><td>原始记录服务</td><td>数据和测试工程师</td><td>CyberRT/MCAP 记录上传、分片下载、断点续传、校验和和生命周期管理</td><td>服务入口待接入</td></tr><tr><td>标注与样本服务</td><td>感知算法开发</td><td>样本筛选、标注版本、导出 Lite 所需格式、训练/验证集冻结</td><td>服务入口待接入</td></tr><tr><td>回放与评测服务</td><td>算法验证</td><td>选择记录、绑定代码提交和配置，运行离线回放并输出指标</td><td>服务入口待接入</td></tr><tr><td>模型制品服务</td><td>模型和部署工程师</td><td>模型、推理配置、TensorRT engine、校验和、硬件/驱动兼容关系</td><td>服务入口待接入</td></tr></tbody></table><p>建议 API 返回统一的 <code>resource_id</code>、<code>version</code>、<code>source_commit</code>、<code>format</code>、<code>checksum</code>、<code>license</code>、<code>access</code>、<code>created_at</code> 和 <code>expires_at</code>，让下载、回放和证据记录可以互相追溯。</p><h2 id="wheelos-地图服务" tabindex="-1">WheelOS 地图服务 <a class="header-anchor" href="#wheelos-地图服务" aria-label="Permalink to &quot;WheelOS 地图服务&quot;">​</a></h2><p>地图服务应围绕 Lite 的定位、路由、感知 ROI、开放空间规划和精准停车提供版本化地图，而不是只提供一个静态压缩包。</p><table tabindex="0"><thead><tr><th>服务</th><th>面向能力</th><th>建议提供的内容</th><th>当前状态</th></tr></thead><tbody><tr><td>地图目录服务</td><td>地图发现和版本选择</td><td>区域、坐标系、覆盖范围、版本、更新时间、适配车型和变更记录</td><td>服务入口待接入</td></tr><tr><td>HD Map 下载服务</td><td>定位、路由和参考线规划</td><td><code>base_map</code>、<code>routing_map</code>、<code>sim_map</code>、拓扑图和生成元数据</td><td>服务入口待接入</td></tr><tr><td>停车场地图服务</td><td>精准停车和开放空间规划</td><td>停车位、车道边界、禁行区、目标位姿、ROI 和场景配置</td><td>服务入口待接入</td></tr><tr><td>地图检查与转换服务</td><td>地图上线前验证</td><td>格式转换、坐标系检查、拓扑检查、规划可用性和差异报告</td><td>服务入口待接入</td></tr></tbody></table><p>地图条目至少应携带坐标系、原点、投影、车辆约束、生成工具版本、输入数据日期、覆盖边界、校验和和回滚版本。地图版本必须与回放记录、规划配置和车辆标定关联。</p><h2 id="资源目录建设建议" tabindex="-1">资源目录建设建议 <a class="header-anchor" href="#资源目录建设建议" aria-label="Permalink to &quot;资源目录建设建议&quot;">​</a></h2><ol><li>**以 Lite 能力为准建目录：**资源只从 <code>modules/</code>、<code>whl-dyn/</code>、<code>scripts/</code> 和 <code>wheelos-service/</code> 的实际能力抽取，不再维护无关的通用数据集推荐。</li><li>**把“模型”和“算法包”分开：**模型是权重、推理配置和部署制品；算法包是可运行的感知、定位、规划、控制或停车功能。</li><li>**服务与代码分开发布：**代码通过 Git 仓库和版本发布，数据/地图通过 WheelOS 服务按权限和版本下载。</li><li>**以任务组织入口：**用户优先按“地面检测、精准停车、动力学标定、回放验证”等任务找到资源，再进入模块目录。</li><li>**保留可复现关系：**每次下载都绑定 Apollo Lite commit、配置版本、模型版本、地图版本、车辆标定和评测结果。</li></ol><p>这套结构仍然延续 <a href="https://developer.horizon.auto/docs/" target="_blank" rel="noreferrer">Horizon 开发者文档</a> 的平台化思路，但将资源边界收敛到 Apollo Lite 的“模型—算法—工具—数据服务—地图服务”闭环。</p>',29)])])}const b=e(l,[["render",d]]);export{m as __pageData,b as default};
